function sideNav(){let groups=role==='Legekontor'?[['Oversikt',[['overview','Oversikt','grid'],['sales','Salg og andel','graph-up'],['payouts','Utbetalinger','credit-card']]],['Nettsiden',[['clinic','Legekontoret','building'],['staffedit','Fastleger','people'],['servicesedit','Tjenester og priser','receipt'],['newsedit','Nyheter','chat-dots']]],['Nettapotek',[['productsedit','Egne produkter','bag'],['recsedit','Anbefalinger','heart-pulse']]]]:[['Drift',[['overview','Oversikt','grid'],['orders','Bestillinger','receipt'],['inventory','Produkter og lager','box-seam']]],['Partnere',[['clinics','Legekontorer','building'],['integrations','Integrasjoner','sliders']]],['Økonomi',[['sales','Salg og andeler','graph-up'],['payouts','Utbetalinger','credit-card']]]];return `<aside class="sidebar refined-sidebar">${groups.map(([title,items])=>`<section class="sidebar-group"><h2>${title}</h2>${items.map(([p,t,i])=>link(p,icon(i)+`<span>${t}</span>`,page===p?'on':'')).join('')}</section>`).join('')}</aside>`}
function periodOrders(){let now=new Date();return db.orders.filter(o=>{let d=new Date(o.date);return (role!=='Legekontor'||o.clinic===(db.activeOffice||'fjordbyen'))&&(period==='all'||period==='today'&&d.toDateString()===now.toDateString()||period==='month'&&d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear())})}
function stats(os=periodOrders()){return os.reduce((s,o)=>{let t=orderTotals(o);s.goods+=t.goods;s.eligible+=t.eligible;s.rx+=t.rx;s.share+=t.share;s.shipping+=o.shipping.price;return s},{goods:0,eligible:0,rx:0,share:0,shipping:0})}
function periodSelect(){return `<select aria-label="Velg periode" style="width:auto;margin:0" onchange="period=this.value;render()">${[['today','I dag'],['month','Denne måneden'],['all','Alle perioder']].map(([v,t])=>`<option value="${v}" ${period===v?'selected':''}>${t}</option>`).join('')}</select>`}
function dashTitle(h,p,select=false){return `<div class="dash-head"><div><span class="eyebrow">${role==='Legekontor'?esc(office().name):role==='Lager'?'HelseWeb lager':'HelseWeb partnerplattform'}</span><h1>${h}</h1><p>${p}</p></div>${select?periodSelect():''}</div>`}
function statCards(){let t=stats(),count=periodOrders().length;return `<div class="grid g3 dashboard-kpis">${[['Omsetning',money(t.goods),'Varer, uten frakt','graph-up'],['Beregnet andel',money(t.share),'75 % egne varer · 25 % øvrige','credit-card'],['Bestillinger',count,'I valgt periode','bag']].map(([l,v,n,i])=>`<div class="stat"><div><small>${l}</small><span class="kpi-icon">${icon(i)}</span></div><strong>${v}</strong><span class="kpi-note">${n}</span></div>`).join('')}</div>`}
function businessNote(){let t=stats();return `<div class="business-model-note">${icon('graph-up')}<div><strong>Egne produkter: 75 % til legekontoret. Øvrige utvalgte apotekvarer: 25 %.</strong><small>Reseptvarer (${money(t.rx)}) og frakt (${money(t.shipping)}) gir ingen andel. Beregnet andel er ikke netto fortjeneste.</small></div></div>`}
function aggregatedSales(){let t=stats(),ranking={};for(let o of periodOrders())for(let x of o.items){if(x.rx)continue;if(!ranking[x.id])ranking[x.id]={name:x.name,qty:0,sales:0,share:0};ranking[x.id].qty+=x.qty;ranking[x.id].sales+=x.price*x.qty;ranking[x.id].share+=x.price*x.qty*itemShareRate(x)}return `<div class="grid g2" style="margin-top:25px"><div class="card"><h3>Omsetning siste 7 dager</h3><small>Vareomsetning uten frakt</small><div class="bar-chart">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let value=periodOrders().filter(o=>new Date(o.date).toDateString()===d.toDateString()).reduce((s,o)=>s+orderTotals(o).goods,0),max=Math.max(1,...Array.from({length:7},(_,j)=>{let date=new Date();date.setDate(date.getDate()-6+j);return periodOrders().filter(o=>new Date(o.date).toDateString()===date.toDateString()).reduce((s,o)=>s+orderTotals(o).goods,0)}));return `<div style="height:${value?Math.max(4,value/max*100):2}%" title="${d.toLocaleDateString('nb-NO')}: ${money(value)}"><span>${d.getDate()}/${d.getMonth()+1}</span></div>`}).join('')}</div></div><div class="card"><h3>Fordeling av omsetning</h3><div class="row"><span>Utvalgte apotekvarer</span><strong>${money(t.eligible)}</strong></div><div class="row"><span>Reseptvarer · samlet beløp</span><strong>${money(t.rx)}</strong></div><div class="row"><span>Samlet vareomsetning</span><strong>${money(t.goods)}</strong></div><div class="row"><span>Frakt · separat</span><strong>${money(t.shipping)}</strong></div><div class="row"><strong>Beregnet andel · 75 % / 25 %</strong><strong>${money(t.share)}</strong></div></div></div><div class="section-head"><h2>Mest solgte apotekvarer</h2></div><div class="card table-wrap"><table><thead><tr><th>Produkt</th><th>Antall</th><th>Omsetning</th><th>Beregnet andel</th></tr></thead><tbody>${Object.values(ranking).sort((a,b)=>b.qty-a.qty).map(r=>`<tr><td>${esc(r.name)}</td><td>${r.qty}</td><td>${money(r.sales)}</td><td>${money(r.share)}</td></tr>`).join('')||'<tr><td colspan="4">Ingen apotekvarer solgt i valgt periode.</td></tr>'}</tbody></table></div>`}
function clinicOverview(){return `${dashTitle('Oversikt','Salg, inntekter og nettsiden til '+esc(office().name),true)}${statCards()}<div class="dashboard-quicklinks">${[['clinic','building','Rediger legekontoret'],['recsedit','heart-pulse','Administrer anbefalinger'],['productsedit','bag','Egne produkter']].map(([p,i,t])=>link(p,icon(i)+t+icon('arrow-up-right'),'dashboard-quicklink')).join('')}</div>${aggregatedSales()}${businessNote()}<div class="privacy-note">${icon('shield-check')} Denne oversikten inneholder samlet statistikk, uten pasientopplysninger eller detaljer om reseptkjøp.</div>`}
function centralOverview(){let low=db.products.filter(p=>p.stock<10);return `${dashTitle('God oversikt. Smidig drift.','Følg legekontorer, bestillinger og vareflyt fra ett sted.',true)}${statCards()}<div class="status-overview">${statuses.map((s,i)=>`<a href="#orders" onclick="orderFilter='${s}';route(role,'orders');return false" class="status-summary"><span>${icon(['receipt','box-seam','truck','check-circle'][i])}${s}</span><strong>${db.orders.filter(o=>o.status===s).length}</strong></a>`).join('')}</div><div class="dashboard-panels"><div class="card"><div class="panel-heading"><h2>Siste bestillinger</h2>${link('orders','Se alle '+icon('arrow-right'))}</div>${orderTable([...db.orders].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,6))}</div><aside class="card dashboard-alerts"><div class="panel-heading"><h2>Trenger oppfølging</h2>${icon('clock')}</div>${low.length?low.map(p=>`<div class="stock-alert"><span>${icon('box-seam')}</span><div><strong>${esc(p.name)}</strong><small>${p.stock} igjen på lager</small></div></div>`).join(''):'<p>Ingen varsler akkurat nå.</p>'}${link('inventory','Åpne lageroversikten '+icon('arrow-right'),'text-link')}<div class="office-mini-summary"><strong>${db.offices.length} tilknyttede legekontorer</strong><p>Profiler, salg og inntektsandeler.</p>${link('clinics','Administrer legekontorer '+icon('arrow-right'))}</div></aside></div>${businessNote()}`}
function orderTable(os,patient=false){return `<div class="table-wrap order-table"><table><thead><tr><th>Bestilling</th><th>${patient?'Dato':'Legekontor'}</th><th>Status</th><th>Levering</th><th>Totalt</th><th></th></tr></thead><tbody>${os.map(o=>`<tr><td><strong>${o.id}</strong>${!patient?`<small>${dateLabel(o.date)}</small>`:''}</td><td>${patient?dateLabel(o.date):esc(office(o.clinic).name)}</td><td><span class="order-status status-${statuses.indexOf(o.status)}">${o.status}</span></td><td>${o.shipping.name}<small>${o.shipping.mode}</small></td><td><strong>${money(orderTotals(o).total)}</strong></td><td>${btn(icon('arrow-up-right')+' Åpne',`route('${role}','order:${o.id}')`,'small light')}</td></tr>`).join('')||'<tr><td colspan="6"><div class="table-empty">Ingen bestillinger i denne oversikten.</div></td></tr>'}</tbody></table></div>`}
function ordersView(){let os=db.orders.filter(o=>(page!=='sent'||['Varene er sendt','Levert'].includes(o.status))&&(orderFilter==='Alle'||o.status===orderFilter)&&(o.id+' '+office(o.clinic).name).toLowerCase().includes(orderSearch.toLowerCase()));return `${dashTitle(page==='sent'?'Sendte bestillinger':'Bestillinger','Følg bestillingen fra mottak til levering.')}<div class="order-toolbar"><div class="order-filter-tabs">${['Alle',...statuses].map(s=>`<button class="${orderFilter===s?'active':''}" onclick="orderFilter='${s}';render()">${s}</button>`).join('')}</div><label><span class="visually-hidden">Søk etter ordre eller legekontor</span><input placeholder="Søk etter ordre eller legekontor" value="${esc(orderSearch)}" onchange="orderSearch=this.value;render()"></label></div><div class="card">${orderTable(os)}</div>`}
function advance(id){let o=db.orders.find(o=>o.id===id);if(!o)return;let n=statuses.indexOf(o.status);if(n>=3)return;if(n===1&&o.items.some(x=>!o.picked.includes(x.id))){toast('Marker alle varer som plukket før du sender ordren');return}o.status=statuses[n+1];o.history.push({status:o.status,at:new Date().toISOString()});save();render();toast('Status oppdatert: '+o.status)}
function pick(id,item,checked){let o=db.orders.find(o=>o.id===id);if(!o||o.status!=='Varene pakkes')return;o.picked=checked?[...new Set([...o.picked,item])]:o.picked.filter(i=>i!==item);save();render()}
function opsOrder(id){let o=db.orders.find(o=>o.id===id);if(!o)return missing();if(role==='Legekontor')return clinicOverview();let n=statuses.indexOf(o.status);return `${dashTitle(o.id,esc(office(o.clinic).name)+' · '+esc(o.patient))}${stepper(o)}<div class="ops-layout"><section class="card"><div class="panel-heading"><h2>${n===1?'Plukk og pakk':'Bestillingens varer'}</h2><span class="order-status status-${n}">${o.status}</span></div>${n===1?o.items.map(x=>`<label class="pick-line"><input type="checkbox" ${o.picked.includes(x.id)?'checked':''} onchange="pick('${id}','${x.id}',this.checked)"><div class="pick-image">${art(product(x.id))}</div><div><span class="item-kind ${x.rx?'kind-rx':''}">${x.rx?'Reseptvare':'Apotekvare'}</span><strong>${esc(x.name)}</strong><small>Plukk ${x.qty} stk. · Hylle ${x.rx?'R-02':'A-04'}</small></div><span>${o.picked.includes(x.id)?icon('check-circle'):'Venter'}</span></label>`).join(''):orderItems(o)}<div class="ops-actions">${n===0?btn('Start pakking '+icon('box-seam'),`advance('${id}')`):n===1?btn('Marker som sendt '+icon('truck'),`advance('${id}')`):n===2?btn('Marker som levert '+icon('check-circle'),`advance('${id}')`):'<span class="completed-order">✓ Bestillingen er levert</span>'}${n>=1?btn('Fraktetikett',`shippingLabel('${id}')`,'light'):''}</div></section><aside class="card delivery-card">${carrierLogo(o.shipping)}<h2>${o.shipping.mode}</h2><p>${esc(o.shipping.place)}</p><div class="row"><span>Forventet levering</span><strong>${o.shipping.time}</strong></div><small>Sporingsnummer</small><strong>${esc(o.tracking)}</strong>${o.patient==='Nora Solheim'&&o.clinic==='fjordbyen'?btn('Åpne pasientens bestilling',`route('Pasient','order:${id}')`,'light'):''}</aside></div><div class="section-head"><h2>Ordrehistorikk</h2></div><div class="card order-history">${o.history.map(h=>`<div class="row"><span>${icon('check-circle')} ${h.status}</span><small>${new Date(h.at).toLocaleString('nb-NO')}</small></div>`).join('')}</div>`}
function shippingLabel(id){let o=db.orders.find(o=>o.id===id);modal(`<h2>Fraktetikett</h2><div class="label-paper">${carrierLogo(o.shipping)}<p>${o.shipping.mode.toUpperCase()}</p><hr><p>Fra: HelseWeb<br>Til: ${esc(o.patient)}<br>${esc(o.shipping.place)}</p><p>Ordre: ${o.id}<br>${o.tracking}</p><div class="barcode"></div></div><small class="label-caption">Forhåndsvisning av fraktetikett. Kan ikke brukes til forsendelse.</small>`)}
function warehouse(){let received=db.orders.filter(o=>o.status==='Mottatt'),packing=db.orders.filter(o=>o.status==='Varene pakkes');return `${dashTitle('Klart for en god arbeidsdag.','Åpne en bestilling, plukk varene og klargjør pakken.')}<div class="grid g3 dashboard-kpis">${[['Mottatt',received.length,'receipt'],['Varene pakkes',packing.length,'box-seam'],['På vei til kunden',db.orders.filter(o=>o.status==='Varene er sendt').length,'truck']].map(([l,v,i])=>`<div class="stat"><div><small>${l}</small><span class="kpi-icon">${icon(i)}</span></div><strong>${v}</strong><span class="kpi-note">Bestillinger</span></div>`).join('')}</div><div class="section-head"><h2>Arbeidskø</h2><span>${received.length+packing.length} bestillinger</span></div><div class="card">${orderTable([...packing,...received])}</div>`}
function payouts(){let offices=role==='Legekontor'?[office()]:db.offices;return `${dashTitle('Utbetalinger','Beregnede andeler og utbetalingsstatus per legekontor.')}<div class="card table-wrap"><table><thead><tr><th>Legekontor</th><th>Beregnet andel</th><th>Utbetalt</th><th>Til utbetaling</th><th>Status</th><th></th></tr></thead><tbody>${offices.map(c=>{let share=stats(db.orders.filter(o=>o.clinic===c.id)).share,paid=db.paidByOffice?.[c.id]||0,pending=Math.max(0,share-paid);return `<tr><td><strong>${esc(c.name)}</strong></td><td>${money(share)}</td><td>${money(paid)}</td><td>${money(pending)}</td><td><span class="order-status ${pending?'status-0':'status-3'}">${pending?'Klar til utbetaling':'Oppdatert'}</span></td><td>${role==='HelseWeb'&&pending?btn('Marker utbetalt',`payOffice('${c.id}')`,'small light'):''}</td></tr>`}).join('')}</tbody></table></div>${businessNote()}`}
function inventory(){return `${dashTitle('Produkter og lager','Priser og beholdning i ett felles vareutvalg.')}<div class="inventory-toolbar"><span>${db.products.length} produkter · ${db.products.filter(p=>p.stock<10).length} med lav beholdning</span>${role==='HelseWeb'?btn(icon('plus')+' Nytt produkt',"editProduct()") :''}</div><div class="card table-wrap"><table><thead><tr><th>Produkt</th><th>Kategori</th><th>Pris</th><th>Lager</th><th>Andel</th><th></th></tr></thead><tbody>${db.products.map(p=>`<tr><td><div class="inventory-product"><div>${art(p)}</div><strong>${esc(p.name)}<small>${esc(p.size)}</small></strong></div></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td><span class="order-status ${p.stock<10?'status-0':'status-3'}">${p.stock} stk.${p.stock<10?' · Lavt':''}</span></td><td>${p.category==='Reseptvarer'?'–':p.own?'75 %':p.eligible?'25 %':'–'}</td><td>${btn('Rediger',`editProduct('${p.id}')`,'small light')}</td></tr>`).join('')}</tbody></table></div>`}
function clinics(){return `${dashTitle('Legekontorene i HelseWeb.','Egne profiler, lokal identitet og ett felles nettapotek.')}<div class="office-toolbar"><span>${db.offices.length} tilknyttede legekontorer</span>${btn(icon('plus')+' Legg til legekontor',"editOffice()")}</div><div class="grid g3 office-cards">${db.offices.map(c=>{let os=db.orders.filter(o=>o.clinic===c.id),t=stats(os);return `<article class="card office-card"><div class="office-card-top"><span class="office-logo" style="--office-color:${esc(c.color)}">${c.logo?`<img alt="${esc(c.name)}" src="${esc(c.logo)}">`:esc(c.initials)}</span><span class="connection-chip">${icon('check-circle')} Tilkoblet</span></div><h2>${esc(c.name)}</h2><p>${icon('geo-alt')} ${esc(c.city)} <span>· ${c.doctors} fastleger</span></p><div class="office-card-metrics"><div><small>Omsetning</small><strong>${money(t.goods)}</strong></div><div><small>Beregnet andel</small><strong>${money(t.share)}</strong></div><div><small>Bestillinger</small><strong>${os.length}</strong></div></div><div class="office-card-actions">${btn('Åpne oversikt '+icon('arrow-right'),`useOffice('${c.id}')`,'small light')}${btn(icon('gear'),`editOffice('${c.id}')`,'small light')}</div></article>`}).join('')}<button class="office-add-card" onclick="editOffice()">${icon('plus')}<strong>Nytt legekontor</strong><span>Koble til et nytt legekontor og opprett en lokal profil.</span></button></div>`}
function clinicEdit(){let c=office().id==='fjordbyen'?db.clinic:office();return `${dashTitle('Legekontorets profil','Informasjon, kontaktopplysninger og åpningstider.')}<form class="card profile-editor" onsubmit="saveClinic(event)"><h2>${esc(c.name)}</h2><div class="grid g2">${[['name','Navn'],['address','Adresse'],['phone','Telefon'],['email','E-post'],['hours','Legekontoret · mandag–fredag'],['telephone','Telefon · mandag–fredag'],['lab','Laboratoriet · mandag–fredag']].map(([k,t])=>field(k,t,c[k]||db.clinic[k])).join('')}</div><label>Presentasjon<textarea name="intro" required>${esc(c.intro||db.clinic.intro)}</textarea></label><button class="btn">Lagre profil</button></form>`}
function field(name,label,value='',type='text'){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${['price','stock'].includes(name)?'min="0" step="1"':''} required></label>`}
function saveClinic(e){e.preventDefault();let f=new FormData(e.target),target=office().id==='fjordbyen'?db.clinic:office();for(let [k,v]of f)target[k]=v.trim();if(office().id==='fjordbyen')Object.assign(office(),{name:target.name,address:target.address,phone:target.phone,email:target.email});save();render();toast('Profilen er oppdatert')}
function management(){let kind=page;if(kind==='staffedit')return `${dashTitle('Ansatte og spesialiteter.','Profilene brukes i tjenester og legens anbefalinger.')}<div class="actions">${btn('Legg til ansatt',"editDoctor()")}</div><div class="grid g3">${db.doctors.map(d=>`<div class="card"><div class="portrait">${portrait(d)}</div><h3>${esc(d.name)}</h3><p>${esc(d.title)}<br><small>${esc(d.specialty)}</small></p>${btn('Rediger',`editDoctor('${d.id}')`,'small light')}</div>`).join('')}</div>`;
if(kind==='servicesedit')return `${dashTitle('Tjenester og priser','Prisliste for legekontoret.')}<div class="actions">${btn('Ny tjeneste',"editService()")}</div><div class="card table-wrap"><table><thead><tr><th>Tjeneste</th><th>Gruppe</th><th>Dagtid</th><th>Kveld</th><th></th></tr></thead><tbody>${db.services.map(s=>`<tr><td>${esc(s.name)}<small>${esc(s.desc||'')}</small></td><td>${esc(s.group||'Egenandel')}</td><td>${servicePrice(s.price)}</td><td>${s.evening===null||s.evening===undefined?'–':servicePrice(s.evening)}</td><td>${btn('Rediger',`editService('${s.id}')`,'small light')}</td></tr>`).join('')}</tbody></table></div>`;
if(kind==='newsedit')return `${dashTitle('Nyheter fra legesenteret.','Oppdater nyhetene som vises på forsiden.')}<div class="actions">${btn('Skriv nyhet',"editNews()")}</div><div class="grid g3">${db.news.map(n=>`<div class="card"><small>${esc(n.date)}</small><h3 style="margin-top:15px">${esc(n.title)}</h3><p>${esc(n.body.slice(0,100))}…</p>${btn('Rediger',`editNews('${n.id}')`,'small light')}</div>`).join('')}</div>`;
if(kind==='productsedit')return `${dashTitle('Legesenterets egne produkter.','Pris, beskrivelse og bilde vises direkte i nettapoteket.')}<div class="actions">${btn('Nytt eget produkt',"editProduct()")}</div><div class="grid g3">${db.products.filter(p=>p.own).map(p=>`<div class="card">${art(p)}<h3>${esc(p.name)}</h3><p>${money(p.price)} · ${p.stock} på lager</p>${btn('Rediger',`editProduct('${p.id}')`,'small light')}</div>`).join('')}</div>`;
return `${dashTitle('Legens anbefalinger.','Knytt generelle og personlige anbefalinger til riktig lege.')}<div class="actions">${btn('Ny anbefaling',"editRec()")}</div><div class="grid g2">${db.recommendations.map(r=>`<div>${recCard(r)}<div style="margin:8px 0 20px">${btn('Rediger anbefaling',`editRec('${r.id}')`,'small light')}</div></div>`).join('')}</div>`}
function doctorSelect(value){return `<label>Ansatt / lege<select name="doctor">${db.doctors.map(d=>`<option value="${d.id}" ${d.id===value?'selected':''}>${esc(d.name)} · ${esc(d.specialty)}</option>`).join('')}</select></label>`}
function editDoctor(id){let d=doctor(id)||{name:'',title:'Fastlege',specialty:'Spesialist i allmennmedisin',focus:'',bio:'',color:'#b7c8b0'};modal(`<h2>${id?'Rediger':'Ny'} ansatt</h2><form onsubmit="storeDoctor(event,'${id||''}')">${field('name','Navn',d.name)}${field('title','Stilling',d.title)}${field('specialty','Spesialitet',d.specialty)}${field('focus','Faglig interesseområde',d.focus||'Allmennmedisin')}<label>Presentasjon<textarea name="bio" required>${esc(d.bio)}</textarea></label><button class="btn">Lagre ansatt</button></form>`)}
function storeDoctor(e,id){e.preventDefault();let data=Object.fromEntries(new FormData(e.target));if(id)Object.assign(doctor(id),data);else db.doctors.push({...data,id:uid('d'),color:'#c2cfb7'});save();closeModal();render();toast('Ansatt er lagret')}
function editService(id){let s=db.services.find(s=>s.id===id)||{name:'',price:null,evening:null,group:'Øvrige tjenester',desc:''};modal(`<h2>${id?'Rediger':'Ny'} tjeneste</h2><form onsubmit="storeService(event,'${id||''}')">${field('name','Tjeneste',s.name)}<label>Gruppe<select name="group"><option ${s.group==='Egenandel'?'selected':''}>Egenandel</option><option ${s.group==='Øvrige tjenester'?'selected':''}>Øvrige tjenester</option></select></label><div class="grid g2"><label>Dagtid · kroner<input name="price" type="number" min="0" step="1" value="${s.price??''}" placeholder="Pris på forespørsel"></label><label>Kveld · kroner<input name="evening" type="number" min="0" step="1" value="${s.evening??''}" placeholder="Ikke oppgitt"></label></div><label>Beskrivelse<textarea name="desc">${esc(s.desc||'')}</textarea></label><button class="btn">Lagre tjeneste</button></form>`)}
function storeService(e,id){e.preventDefault();let data=Object.fromEntries(new FormData(e.target));data.price=data.price===''?null:Number(data.price);data.evening=data.evening===''?null:Number(data.evening);data.note='';if(id)Object.assign(db.services.find(s=>s.id===id),data);else db.services.push({...data,id:uid('s')});save();closeModal();render();toast('Tjenesten er oppdatert')}
function editNews(id){let n=db.news.find(n=>n.id===id)||{title:'',tag:'Aktuelt',date:new Date().toLocaleDateString('nb-NO',{day:'numeric',month:'long',year:'numeric'}),body:''};modal(`<h2>${id?'Rediger':'Skriv'} nyhet</h2><form onsubmit="storeNews(event,'${id||''}')">${field('title','Overskrift',n.title)}${field('tag','Kategori',n.tag)}${field('date','Dato',n.date)}<label>Artikkeltekst<textarea name="body" required style="min-height:160px">${esc(n.body)}</textarea></label><button class="btn">Lagre nyhet</button></form>`)}
function storeNews(e,id){e.preventDefault();let data=Object.fromEntries(new FormData(e.target));if(id)Object.assign(db.news.find(n=>n.id===id),data);else db.news.unshift({...data,id:uid('n')});save();closeModal();render();toast('Nyheten er lagret')}
function editProduct(id){let p=product(id)||{name:'',price:0,stock:10,category:'Hudpleie',size:'1 stk.',desc:'',eligible:true,own:role==='Legekontor',tone:'#b9c697'};modal(`<h2>${id?'Rediger':'Nytt'} produkt</h2><form onsubmit="storeProduct(event,'${id||''}')"><div class="grid g2">${field('name','Produktnavn',p.name)}${field('size','Størrelse / pakning',p.size)}${field('price','Pris i kr',p.price,'number')}${field('stock','Lagerbeholdning',p.stock,'number')}</div><label>Kategori<select name="category">${['Hudpleie','Solpleie','Munn og tann','Sår og førstehjelp',...(role==='HelseWeb'?['Reseptvarer']:[])].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Beskrivelse<textarea name="desc" required>${esc(p.desc)}</textarea></label><label>Lokalt produktbilde (valgfritt)<input name="imageFile" type="file" accept="image/png,image/jpeg,image/webp"></label><small>Bilder lagres i nettleseren. Maks. 500 kB.</small><div class="actions"><button class="btn">Lagre produkt</button></div></form>`)}
async function storeProduct(e,id){e.preventDefault();let fd=new FormData(e.target),data={name:fd.get('name'),size:fd.get('size'),price:Number(fd.get('price')),stock:Number(fd.get('stock')),category:fd.get('category'),desc:fd.get('desc')},file=fd.get('imageFile');if(file&&file.size){if(file.size>500000){toast('Velg et bilde under 500 kB');return}data.image=await new Promise(resolve=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(file)})}if(id)Object.assign(product(id),data,{eligible:data.category!=='Reseptvarer'});else db.products.push({...data,id:uid('p'),eligible:data.category!=='Reseptvarer',own:role==='Legekontor',tone:'#b9c697'});save();closeModal();render();toast('Produktet er lagret')}
function editRec(id){let r=db.recommendations.find(r=>r.id===id)||{product:'p1',doctor:'d2',personal:false,reason:''};modal(`<h2>${id?'Rediger':'Ny'} anbefaling</h2><form onsubmit="storeRec(event,'${id||''}')">${doctorSelect(r.doctor)}<label>Produkt<select name="product" aria-label="Velg produkt">${db.products.filter(p=>p.category!=='Reseptvarer').map(p=>`<option value="${p.id}" ${p.id===r.product?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Synlighet<select name="personal"><option value="false" ${!r.personal?'selected':''}>Generell · synlig for alle</option><option value="true" ${r.personal?'selected':''}>Personlig · Nora Solheim etter innlogging</option></select></label><label>Kort begrunnelse<textarea name="reason" required>${esc(r.reason)}</textarea></label><button class="btn">Lagre anbefaling</button></form>`)}
function storeRec(e,id){e.preventDefault();let data=Object.fromEntries(new FormData(e.target));data.personal=data.personal==='true';if(id)Object.assign(db.recommendations.find(r=>r.id===id),data);else db.recommendations.push({...data,id:uid('r')});save();closeModal();render();toast('Anbefalingen er lagret')}
function patientView(){if(page==='home')return home();if(page==='contact')return contact();if(page==='staff')return staff();if(page==='info')return info();if(page==='bankid')return bankPage();if(page==='shop')return shop();if(page.startsWith('product:'))return productPage(page.split(':')[1]);if(page==='prescriptions')return prescriptions();if(page==='recommendations')return recommendations();if(page==='cart')return cart();if(page==='checkout')return checkout();if(page==='account')return account();if(page.startsWith('confirmation:')||page.startsWith('order:'))return orderPage(page.split(':')[1],page.startsWith('confirmation:'));return missing()}

function dashboard(){if(page==='integrations')return integrationsView();if(page.startsWith('order:'))return opsOrder(page.split(':')[1]);if(page==='overview')return role==='Legekontor'?clinicOverview():role==='HelseWeb'?centralOverview():warehouse();if(page==='orders'||page==='sent')return ordersView();if(page==='sales')return `${dashTitle('Salg og beregnet andel','Samlet salg og inntektsgrunnlag for valgt periode.',true)}${statCards()}${aggregatedSales()}${businessNote()}`;if(page==='payouts')return payouts();if(page==='inventory')return inventory();if(page==='clinics')return clinics();if(page==='clinic')return clinicEdit();return management()}
function render(){$('#app').innerHTML=header()+(role==='Pasient'?((['shop','prescriptions','recommendations','account','cart','checkout','bankid'].includes(page)||page.startsWith('product:')||page.startsWith('order:')||page.startsWith('confirmation:')?pharmacyNav():'')+patientView()):`<div class="layout">${sideNav()}<main class="dash">${dashboard()}</main></div>`)+footer();bindLinks()}
function bindLinks(){document.querySelectorAll('[data-page]').forEach(a=>a.onclick=e=>{e.preventDefault();route(role,a.dataset.page)})}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});window.addEventListener('storage',e=>{if(e.key===KEY){db=JSON.parse(e.newValue)||seed();render()}});
let orderFilter='Alle',orderSearch='';
function editOffice(id){let c=id?office(id):{name:'',city:'',address:'',phone:'',email:'',initials:'',color:'#527d69',doctors:3};modal(`<h2>${id?'Rediger':'Legg til'} legekontor</h2><form onsubmit="storeOffice(event,'${id||''}')"><div class="grid g2">${field('name','Navn',c.name)}${field('city','By',c.city)}${field('address','Adresse',c.address)}${field('phone','Telefon',c.phone)}${field('email','E-post',c.email||'')}${field('doctors','Antall fastleger',c.doctors,'number')}</div><label>Logo (valgfritt)<input name="logo" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"></label><p class="muted">Uten opplastet logo brukes legekontorets initialer.</p><button class="btn">${id?'Lagre profil':'Legg til legekontor'}</button></form>`)}
async function storeOffice(e,id){e.preventDefault();let fd=new FormData(e.target),data={name:fd.get('name').trim(),city:fd.get('city').trim(),address:fd.get('address').trim(),phone:fd.get('phone').trim(),email:fd.get('email').trim(),doctors:Number(fd.get('doctors')),initials:fd.get('name').trim()[0].toUpperCase()},file=fd.get('logo');if(file?.size){if(file.size>500000){toast('Velg en logo under 500 kB');return}data.logo=await new Promise(resolve=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(file)})}if(id){Object.assign(office(id),data);if(id==='fjordbyen')Object.assign(db.clinic,{name:data.name,address:data.address,phone:data.phone,email:data.email})}else db.offices.push({...data,id:uid('office-'),color:['#5f718f','#a47b5f','#837795','#527d69'][db.offices.length%4]});save();closeModal();render();toast('Legekontoret er lagret')}
function payOffice(id){db.paidByOffice=db.paidByOffice||{};db.paidByOffice[id]=stats(db.orders.filter(o=>o.clinic===id)).share;save();render();toast('Utbetalingsstatus er oppdatert')}

// Local staff sessions and connected consultation/warehouse workspaces.
const staffSessions=new Set();const parcelResumeTimers=new Set();let scanLightUntil=0,lastScannedProduct='';let terminalTab='queue',terminalSentOrder='';let terminalOrder='',consultationPatient='Nora Solheim',clinicalTab='journal';
function staffLogin(){if(role==='Lege')return doctorLockScreen();return `<main class="staff-login"><section class="card">${role==='Lege'?`<div class="external-login-brand"><img src="${assetSrc('assets/pasientsky-logo.svg')}" alt="Pasientsky logo"><strong>Pasientsky</strong></div>`:`<span class="eyebrow">${esc(role)} · HelseWeb</span>`}<h1>Logg inn</h1><p>Åpne arbeidsområdet ditt.</p><form onsubmit="staffSignIn(event)"><label>Brukernavn<input name="username" autocomplete="off" required placeholder="${role==='HelseWeb'?'helseweb':role==='Lege'?'martin':'fjordbyen'}"></label><label>Passord<input name="password" type="password" autocomplete="off" required></label><button type="button" class="fill-example staff-fill" onclick="fillStaffLogin(this)">Fyll ut ${icon('arrow-right')}</button><p id="staffLoginError" role="alert"></p><button class="btn">Logg inn ${icon('arrow-right')}</button></form><small>Bruk eksempelinnloggingen.</small></section></main>`}
function fillStaffLogin(button){const form=button.closest('form');if(role==='Lege'){form.elements.pin.value='2468';form.elements.pin.focus();$('#staffLoginError').textContent='';return}form.elements.username.value=role==='HelseWeb'?'helseweb':role==='Lege'?'martin':'fjordbyen';form.elements.password.value='velkommen';form.elements.username.focus();const error=$('#staffLoginError');if(error)error.textContent=''}
function staffSignIn(e){e.preventDefault();const f=new FormData(e.target);if(role==='Lege'){if(f.get('pin')!=='2468'){$('#staffLoginError').textContent='Feil PIN-kode. Prøv igjen.';return}staffSessions.add('Lege');render();return}const name=role==='HelseWeb'?'helseweb':role==='Lege'?'martin':'fjordbyen';if(f.get('username')!==name||f.get('password')!=='velkommen'){$('#staffLoginError').textContent='Kontroller brukernavn og passord.';return}staffSessions.add(role);render()}
function staffSignOut(){staffSessions.delete(role);render()}
function scanCode(p){return 'V'+String(p.id.slice(1)).padStart(6,'0')}
function warehouseTerminal(){let queue=db.orders.filter(o=>['Mottatt','Varene pakkes'].includes(o.status));let o=db.orders.find(o=>o.id===terminalOrder);if(!o||!queue.includes(o)){o=queue[0];terminalOrder=o?.id||''}if(o){if(o.packed&&o.labelPrinted&&!o.packStage){o.labelApplied=true;o.packStage='ready'}if(o.packStartedAt&&!o.labelApplied){const elapsed=Date.now()-o.packStartedAt;if(elapsed>=2300){o.packed=true;o.labelPrinted=true;o.labelApplied=true;o.packStage='ready'}else if(!parcelResumeTimers.has(o.id)){const id=o.id;parcelResumeTimers.add(id);setTimeout(()=>{parcelResumeTimers.delete(id);advanceParcelStage(id,'ready')},2300-elapsed)}}o.scanCounts=o.scanCounts||{};for(let x of o.items)if(o.picked.includes(x.id))o.scanCounts[x.id]=x.qty}const next=o?.items.find(x=>(o.scanCounts[x.id]||0)<x.qty),p=next?product(next.id):null,total=o?.items.reduce((n,x)=>n+x.qty,0)||0,done=o?.items.reduce((n,x)=>n+Math.min(x.qty,o.scanCounts[x.id]||0),0)||0,printerOrder=terminalTab==='sent'?db.orders.find(x=>x.id===terminalSentOrder):o;return `<main class="warehouse-station"><div class="station-heading"><div><h1>Plukk. Pakk. Send.</h1></div></div><div class="warehouse-scene"><section class="handheld-area"><div class="scanner-head ${Date.now()<scanLightUntil?'scanning':''}"><span></span><i></i><b>Håndterminal · HW-01</b></div><div class="handheld"><div class="terminal-top">${icon('box-seam')} HelseWeb WMS <span>● WLAN · 98 %</span></div><nav class="terminal-tabs" aria-label="Håndterminal">${[['queue','Ordrekø'],['pick','Plukk'],['inventory','Lager'],['sent','Sendt']].map(([id,t])=>`<button class="${terminalTab===id?'active':''}" onclick="terminalTab='${id}';render()">${t}</button>`).join('')}</nav>${terminalTab!=='pick'?terminalPanel(queue):''}${terminalTab==='pick'?(o?`<div class="terminal-screen"><small>AKTIV BESTILLING</small><h2>${o.id}</h2><p>${esc(o.patient)} · ${esc(o.shipping.name)}</p><div class="scan-progress"><span style="width:${done/total*100}%"></span></div><div class="scan-count">${done} av ${total} enheter plukket</div>${next?`<div class="terminal-location">${icon('geo-alt')} Hylle ${next.rx?'R-02':'A-04'}</div><div class="terminal-product">${art(p)}<h3>${esc(next.name)}</h3><p>Plukk ${next.qty-(o.scanCounts[next.id]||0)} stk.</p><code>${scanCode(p)}</code></div>${btn(icon('camera-video')+' Skann',"simulateWarehouseScan()",'scanner-trigger')}`:`<div class="terminal-complete">${icon('check-circle')}<h3>Alle varer plukket</h3><p>${o.packStage==='printing'?'Skriver ut etikett …':o.packStage==='closing'?'Lukker esken …':'Pakken er klar.'}</p></div>`}<div class="terminal-lines">${o.items.map(x=>`<div><span>${esc(x.name)}</span><strong>${o.scanCounts[x.id]||0}/${x.qty} ${o.picked.includes(x.id)?'✓':''}</strong></div>`).join('')}</div>${terminalPackingControls(o)}</div>`:'<div class="terminal-screen"><h2>Ingen oppgaver</h2><p>Nye bestillinger vises automatisk her.</p></div>') : ''}<div class="terminal-hardware">◁ <span>○</span> □</div></div><div class="scanner-grip"></div></section><section class="packing-bench"><div class="bench-heading"><h2>${icon('box-seam')} Pakkestasjon</h2><span>Benk 04</span></div>${warehouseParcel(o)}<div class="label-printer"><div class="printer-body"><span>ETIKETTSKRIVER</span><i class="printer-light"></i><div class="printer-slot"></div></div>${printerOrder?.labelPrinted&&(!printerOrder.labelApplied||printerOrder.printAgain)?`<div class="thermal-label" style="animation-delay:-${Math.min(1000,Math.max(0,Date.now()-(printerOrder.labelPrintAt||printerOrder.packStartedAt||0)))}ms;animation-fill-mode:both">${carrierLogo(printerOrder.shipping)}<span>${esc(printerOrder.patient)}</span><small>${esc(printerOrder.shipping.place)}</small><div class="barcode"></div><b>${printerOrder.tracking}</b><small>${printerOrder.id}</small></div>`:''}</div></section></div></main>`}
function warehouseActive(){return db.orders.find(o=>o.id===terminalOrder)}
function scanWarehouse(e){e.preventDefault();const code=new FormData(e.target).get('barcode').trim();registerWarehouseScan(code)}
function simulateWarehouseScan(){let o=warehouseActive(),x=o?.items.find(x=>(o.scanCounts[x.id]||0)<x.qty);if(x)registerWarehouseScan(scanCode(product(x.id)))}
function registerWarehouseScan(code){let o=warehouseActive();if(!o)return;let x=o.items.find(x=>scanCode(product(x.id))===code||x.id===code);if(!x){toast('Ukjent vare. Skann en vare fra denne bestillingen.');return}if((o.scanCounts[x.id]||0)>=x.qty){toast('Riktig antall er allerede registrert');return}if(o.status==='Mottatt'){o.status='Varene pakkes';o.history.push({status:o.status,at:new Date().toISOString()})}o.scanCounts[x.id]=(o.scanCounts[x.id]||0)+1;if(o.scanCounts[x.id]===x.qty)o.picked=[...new Set([...o.picked,x.id])];scanLightUntil=Date.now()+550;lastScannedProduct=x.id;if(warehouseAllPicked(o)){o.packStage='printing';o.packStartedAt=Date.now();o.labelPrintAt=o.packStartedAt;o.labelPrinted=true;o.labelApplied=false;const id=o.id;setTimeout(()=>advanceParcelStage(id,'closing'),1100);setTimeout(()=>advanceParcelStage(id,'ready'),2300)}save();render();setTimeout(()=>{lastScannedProduct='';if(role==='Lager')render()},600)}
function warehouseAllPicked(o){return o&&o.items.every(x=>(o.scanCounts[x.id]||0)>=x.qty)}
function sealWarehouseParcel(){let o=warehouseActive();if(!warehouseAllPicked(o)){toast('Skann alle enhetene før du lukker pakken');return}o.packed=true;if(db.autoPrintLabel!==false)o.labelPrinted=true;save();render()}
function printWarehouseLabel(){let o=warehouseActive();if(!o?.packed)return;o.labelPrinted=true;o.labelPrintAt=Date.now();o.printAgain=true;save();render();setTimeout(()=>{o.printAgain=false;save();if(role==='Lager')render()},1800)}
function dispatchWarehouse(){let o=warehouseActive();if(!warehouseAllPicked(o)||!o.packed||!o.labelPrinted||!o.labelApplied)return;o.status='Varene er sendt';o.history.push({status:o.status,at:new Date().toISOString()});save();terminalOrder='';terminalTab='queue';render();toast('Pakken er overlevert til '+o.shipping.name)}
const doctorAppointments=[['08.30','Kari Nilsen','Kontroll'],['09.00','Nora Solheim','Oppfølging og resept'],['09.30','Ola Hansen','Årskontroll'],['10.00','Amir Berg','Konsultasjon'],['10.30','Ingrid Olsen','Prøvesvar'],['11.00','Per Lund','Oppfølging'],['11.30','Emma Vik','Konsultasjon']];
function doctorWorkspace(){let nora=consultationPatient==='Nora Solheim';return `<main class="clinical-workspace classic-epr"><aside class="appointment-book"><span class="eyebrow">Martin Dahl · Fastlege</span><h2>Dagens timer</h2><p>${new Date().toLocaleDateString('nb-NO',{weekday:'long',day:'numeric',month:'long'})}</p><label class="visually-hidden" for="patientSearch">Søk blant pasientene</label><input id="patientSearch" placeholder="Søk blant pasientene" oninput="filterAppointments(this.value)"><div id="appointmentList">${doctorAppointments.map(([t,n,r])=>`<button data-patient="${n}" class="${n===consultationPatient?'active':''}" onclick="consultationPatient='${n}';render()"><time>${t}</time><span><strong>${n}</strong><small>${r}</small></span></button>`).join('')}</div><small>7 avtaler · 30 minutter per time</small><div class="epr-module-list"><h3>Arbeidslister</h3>${['Innboks og meldinger','Laboratoriesvar','Reseptforespørsler','Henvisninger','Sykmeldinger','Dagsoppgjør'].map(t=>`<button disabled>${icon('clipboard-check')} ${t}</button>`).join('')}</div></aside><section class="consultation-content"><div class="consultation-header"><div><span class="eyebrow">Konsultasjon · ${doctorAppointments.find(a=>a[1]===consultationPatient)?.[0]}</span><h1>${esc(consultationPatient)}</h1><p>${nora?'Født 14.06.1988 · Fastlege Martin Dahl · Fjordbyen legesenter':'Pasient i dagens timebok'}</p></div><span class="clinical-connected">${icon('shield-check')} Aktiv konsultasjon</span></div><div class="epr-patient-strip"><span><b>Pasient:</b> ${esc(consultationPatient)}</span><span><b>Fastlege:</b> Martin Dahl</span><span><b>Konsultasjon:</b> Oppfølging</span><span class="epr-cave"><b>CAVE:</b> Ikke registrert</span></div><nav class="epr-record-modules" aria-label="Journalmoduler">${['Oversikt','Diagnoser','Legemidler','Laboratorium','Henvisning','Sykmelding','Attester','Vaksiner','Dokumenter','Meldinger','Regningskort'].map(t=>`<button type="button" disabled>${t}</button>`).join('')}</nav>${!nora?`<div class="card"><h2>Time valgt</h2><p>Den sammenhengende pasientreisen er tilgjengelig for Nora Solheim.</p>${btn('Åpne Nora sin time',"consultationPatient='Nora Solheim';render()")}</div>`:`<div class="clinical-tabs">${[['journal','Journal og konsultasjon'],['prescription','Resept'],['recommend','Anbefal produkter (HelseWeb)']].map(([id,t])=>`<button class="${clinicalTab===id?'active':''}" onclick="clinicalTab='${id}';render()">${t}</button>`).join('')}</div>${clinicalTab==='journal'?`<div class="clinical-columns"><form class="card consultation-note" onsubmit="saveConsultationNote(event)"><div class="epr-window-title">Løpende journal · ${new Date().toLocaleDateString('nb-NO')} · Martin Dahl</div><div class="epr-note-tools"><span>Notattype: Konsultasjon</span>${['Mal','B','I','Punktliste','Sett inn'].map(t=>`<button type="button" disabled>${t}</button>`).join('')}</div><label>Konsultasjonsnotat<textarea name="note" rows="9" placeholder="Skriv notat fra timen …">${esc(db.consultationNote||'Oppfølging av hudplager og gjennomgang av faste resepter. Pasienten ønsker råd om daglig hudpleie.')}</textarea></label><div class="epr-note-actions"><button class="btn">Lagre journalnotat</button><button type="button" disabled>Signer og lukk</button><button type="button" disabled>Utskrift</button></div><div class="epr-history"><h3>Journaloversikt</h3><table><thead><tr><th>Dato</th><th>Type</th><th>Behandler</th><th>Innhold</th></tr></thead><tbody><tr><td>20.09.2026</td><td>Konsultasjon</td><td>MDAL</td><td>Oppfølging av hudplager</td></tr><tr><td>12.08.2026</td><td>Resept</td><td>MDAL</td><td>Gjennomgang av resepter</td></tr><tr><td>03.06.2026</td><td>Notat</td><td>MDAL</td><td>Avtale om videre oppfølging</td></tr></tbody></table></div></form><aside class="card"><h2>Pasientoversikt</h2><div class="epr-summary-fields"><div><span>Kontaktårsak</span><strong>Oppfølging og resept</strong></div><div><span>Ansvarlig lege</span><strong>Martin Dahl</strong></div><div><span>Konsultasjonstype</span><strong>Ordinær time</strong></div></div><p>${db.prescriptions.filter(r=>r.status==='active').length} aktive resepter</p><p>${db.recommendations.filter(r=>r.personal).length} personlige produktanbefalinger</p><hr><h3>Nettapotek</h3><p>Resepter og anbefalinger vises i Nora sitt nettapotek.</p>${btn('Skriv resept',"clinicalTab='prescription';render()",'light')}${btn('Anbefal et produkt',"clinicalTab='recommend';render()",'light')}</aside></div>`:clinicalTab==='prescription'?`<div class="clinical-columns"><form class="card" onsubmit="saveClinicalPrescription(event)"><div class="clinical-helseweb-brand prescription-brand-reminder">${icon('heart-pulse')}<strong>HelseWeb</strong><span>Minn pasienten på å handle reseptene i legekontorets nettapotek.</span></div><h2>Skriv eller forny resept</h2><label>Legemiddel<select name="product" aria-label="Legemiddel">${db.products.filter(p=>p.category==='Reseptvarer').map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.size)}</option>`).join('')}</select></label><label>Dosering og merknad<input name="dosage" required placeholder="Legens dosering og bruksanvisning"></label><label>Bruksområde<input name="purpose" required placeholder="Kort beskrivelse"></label><div class="grid g2"><label>Gyldig til<input name="expires" type="date" min="${new Date().toISOString().slice(0,10)}" required></label><label>Antall uttak<input name="refills" type="number" min="1" max="12" value="3" required></label></div><button class="btn">Lagre resept til Nora</button><small></small></form><aside class="card"><h2>Registrerte resepter</h2>${db.prescriptions.map(r=>`<div class="clinical-record"><strong>${esc(product(r.product).name)}</strong><p>${esc(r.dosage||'')}<br>Martin Dahl · ${dateLabel(r.expires)}</p></div>`).join('')}</aside></div>`:`<div class="clinical-columns"><form class="card" onsubmit="saveClinicalRecommendation(event)"><div class="clinical-helseweb-brand">${icon('heart-pulse')}<strong>HelseWeb</strong></div><h2>Anbefal til Nora</h2><label>Velg produkt<select name="product" aria-label="Velg produkt">${db.products.filter(p=>p.category!=='Reseptvarer').map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.size)}</option>`).join('')}</select></label><label>Hvorfor anbefales produktet?<textarea name="reason" rows="5" required placeholder="Skriv en kort, personlig begrunnelse som Nora får se."></textarea></label><button class="btn">Del anbefaling med Nora</button><small></small></form><aside class="card"><h2>Anbefalt for Nora</h2>${db.recommendations.filter(r=>r.personal).map(r=>`<div class="clinical-record"><div class="clinical-product-art">${art(product(r.product))}</div><strong>${esc(product(r.product).name)}</strong><p>${esc(r.reason)}</p></div>`).join('')||'<p>Ingen anbefalinger ennå.</p>'}</aside></div>`}`}</section></main>`}
function filterAppointments(v){document.querySelectorAll('#appointmentList button').forEach(b=>b.hidden=!b.dataset.patient.toLowerCase().includes(v.toLowerCase()))}
function saveConsultationNote(e){e.preventDefault();db.consultationNote=new FormData(e.target).get('note');save();toast('Journalnotatet er lagret lokalt')}
function saveClinicalPrescription(e){e.preventDefault();const f=new FormData(e.target),id=f.get('product'),today=new Date().toISOString().slice(0,10);let r=db.prescriptions.find(r=>r.product===id);const values={product:id,doctor:'d2',issued:today,expires:f.get('expires'),refills:Number(f.get('refills')),status:'active',type:'Blå resept',dosage:f.get('dosage'),purpose:f.get('purpose'),instruction:'Eksempelresept i en lokal forhåndsvisning. Ikke en gyldig resept eller personlig doseringsanbefaling.',lastPickup:'Ikke hentet'};if(r){const used=db.orders.flatMap(o=>o.items).filter(x=>x.id===id&&x.rx).reduce((n,x)=>n+x.qty,0);Object.assign(r,values,{refills:values.refills+used})}else db.prescriptions.push({...values,id:uid('RX-')});save();render();toast('Resepten er tilgjengelig i Nora sin reseptoversikt')}
function saveClinicalRecommendation(e){e.preventDefault();const f=new FormData(e.target);let r=db.recommendations.find(r=>r.personal&&r.product===f.get('product'));if(r){r.reason=f.get('reason');r.doctor='d2'}else db.recommendations.push({id:uid('r'),doctor:'d2',product:f.get('product'),personal:true,reason:f.get('reason')});save();render();toast('Anbefalingen vises under Anbefalt for deg hos Nora')}
const renderStandard=render;
render=function(){if(['HelseWeb','Legekontor','Lege'].includes(role)&&!staffSessions.has(role)){$('#app').innerHTML=header()+staffLogin();bindLinks();return}if(role==='Lege'||role==='Lager'){$('#app').innerHTML=header()+(role==='Lege'?doctorWorkspace():warehouseTerminal());bindLinks()}else renderStandard();if(['HelseWeb','Legekontor','Lege'].includes(role)&&staffSessions.has(role)){const meta=role==='Lege'?$('.external-doctor-account'):$('.workspace-meta');if(meta)meta.insertAdjacentHTML('beforeend',`<button class="workspace-signout" onclick="staffSignOut()">${role==='Lege'?'Lås skjerm':'Logg ut'}</button>`)}};


function externalDoctorUrl(){return '#legesystem'}
function externalDoctorHeader(){return roleLauncher()+`<header class="external-doctor-header classic-epr-header"><div class="external-doctor-brand"><img src="${assetSrc('assets/pasientsky-logo.svg')}" alt="Pasientsky logo"><span>Pasientsky<small>Fjordbyen legesenter · Martin Dahl</small></span></div><div class="epr-title-context">Elektronisk pasientjournal</div><div class="external-doctor-account">${icon('person-circle')} MDAL · Martin Dahl ${!staffSessions.has('Lege')?'<span class="epr-locked-status">Låst</span>':''}</div></header><div class="epr-system-menu" aria-label="Systemmeny">${['Fil','Pasient','Journal','Timebok','Kommunikasjon','Laboratorium','Regnskap','Verktøy','Hjelp'].map(t=>`<button disabled>${t}</button>`).join('')}<span>Fjordbyen legesenter</span></div><div class="epr-system-toolbar">${[['person-circle','Pasientsøk'],['calendar3','Timebok'],['envelope','Innboks'],['clipboard-check','Arbeidsliste'],['receipt','Oppgjør'],['gear','Innstillinger']].map(([i,t])=>`<button disabled>${icon(i)} ${t}</button>`).join('')}</div>`}
function integrationsView(){return `${dashTitle('Integrasjoner med journalsystemer','HelseWeb kobler legekontorets nettapotek til legens eksisterende arbeidsflate.')}<div class="integration-cards"><article class="card"><img class="integration-logo" src="${assetSrc('assets/pasientsky-logo.svg')}" alt="Pasientsky logo"><h2>Pasientsky</h2><span class="connection-chip">Illustrert integrasjon</span><p>Eksternt journalsystem med timebok og konsultasjon. HelseWeb-panelet knytter Nora sine resepter og anbefalinger til nettapoteket.</p><div class="integration-feature-list"><span>${icon('check-circle')} Pasientkobling: Nora Solheim</span><span>${icon('capsule')} Reseptoversikt</span><span>${icon('heart-pulse')} Personlige produktanbefalinger</span></div><a class="btn light" onclick="openExternalDoctor(event)" href="${externalDoctorUrl()}">Åpne PasientSky ${icon('arrow-up-right')}</a></article><article class="card"><span class="integration-logo placeholder-logo">${icon('building')}</span><h2>Andre journalsystemer</h2><span class="pill">Integrasjonsmodell</span><p>Samme HelseWeb-modul kan illustreres i flere eksterne journalsystemer. Leverandør, tilgang og datakobling avklares for hver integrasjon.</p><div class="integration-feature-list"><span>${icon('sliders')} Eget journalsystem og egen innlogging</span><span>${icon('shield-check')} Kun valgt informasjon deles</span><span>${icon('bag')} Ett tilknyttet nettapotek</span></div></article></div><div class="business-model-note">${icon('shield-check')} Prototypen viser en tenkt integrasjon. Den dokumenterer ingen eksisterende avtale eller teknisk tilkobling til EG eller andre journalleverandører.</div>`}

function openExternalDoctor(e){e.preventDefault();route('Lege','overview')}
function terminalPanel(queue){if(terminalTab==='queue')return `<div class="terminal-screen terminal-list"><h2>Ordrekø</h2><p>${queue.length} bestillinger</p>${queue.map(o=>`<button class="terminal-order" onclick="terminalOrder='${o.id}';terminalTab='pick';render()"><strong>${o.id}</strong><span>${esc(o.patient)}</span><small>${o.items.reduce((n,x)=>n+x.qty,0)} enheter · ${o.status}</small>${icon('arrow-right')}</button>`).join('')||'<p>Ingen ventende bestillinger.</p>'}</div>`;if(terminalTab==='inventory')return `<div class="terminal-screen terminal-list"><h2>Lagerbeholdning</h2><label>Søk vare<input placeholder="Navn eller varekode" oninput="filterTerminalInventory(this.value)"></label><div class="terminal-inventory">${db.products.map(p=>`<div data-stock-search="${esc((p.name+' '+scanCode(p)).toLowerCase())}"><strong>${esc(p.name)}</strong><span>${p.stock} stk.</span><small>${scanCode(p)} · ${p.category==='Reseptvarer'?'R-02':'A-04'}</small></div>`).join('')}</div></div>`;let sent=db.orders.filter(o=>['Varene er sendt','Levert'].includes(o.status)),selected=sent.find(o=>o.id===terminalSentOrder);return `<div class="terminal-screen terminal-list"><h2>Sendte ordre</h2>${sent.map(o=>`<button class="terminal-order" onclick="terminalSentOrder='${o.id}';render()"><strong>${o.id}</strong><span>${esc(o.patient)}</span><small>${o.status} · ${o.shipping.name}</small>${icon('receipt')}</button>`).join('')||'<p>Ingen sendte ordre.</p>'}${selected?`<div class="terminal-label-preview"><h3>${selected.id}</h3><p>${selected.tracking}</p><div class="barcode"></div></div>`:''}</div>`}
function terminalPackingControls(o){return `<div class="terminal-packing">${o.labelApplied?`<span class="terminal-ready">${icon('check-circle')} Pakket og merket</span>`:''}<button class="btn dispatch-button" ${!warehouseAllPicked(o)||!o.labelApplied?'disabled':''} onclick="dispatchWarehouse()">${icon('truck')} Overlever til transportør</button></div>`}
function filterTerminalInventory(v){document.querySelectorAll('[data-stock-search]').forEach(el=>el.hidden=!el.dataset.stockSearch.includes(v.toLowerCase()))}
function reprintSentLabel(){const o=db.orders.find(o=>o.id===terminalSentOrder);if(!o)return;o.labelPrinted=true;o.labelPrintAt=Date.now();o.printAgain=true;save();render();setTimeout(()=>{o.printAgain=false;save();if(role==='Lager')render()},1800)}

function advanceParcelStage(id,stage){const o=db.orders.find(x=>x.id===id);if(!o||!warehouseAllPicked(o)||o.status!=='Varene pakkes'||o.labelApplied||['printing','closing','ready'].indexOf(stage)<=['printing','closing','ready'].indexOf(o.packStage))return;o.packStage=stage;if(stage==='closing')o.packed=true;if(stage==='ready'){o.packed=true;o.labelPrinted=true;o.labelApplied=true}save();if(role==='Lager')render()}
function warehouseParcel(o){const items=o?o.items.flatMap(x=>Array.from({length:Math.min(x.qty,o.scanCounts?.[x.id]||0)},(_,i)=>({p:product(x.id),key:x.id+'-'+i}))):[];return `<div class="parcel-scene ${o?.packed?'is-closed':'is-open'} ${o?.packStage||''}"><div class="box-flap flap-left"></div><div class="box-flap flap-right"></div><div class="shipping-parcel"><div class="box-interior"><div class="box-products">${items.map((x,i)=>`<div class="box-product ${x.p.id===lastScannedProduct&&i===items.length-1?'just-scanned':''}" style="--tilt:${i%2?-7:8}deg">${x.p.image?`<img src="${assetSrc(x.p.image)}" alt="${esc(x.p.name)}">`:art(x.p)}<small>${esc(x.p.name)}</small></div>`).join('')||'<span class="empty-box-mark">＋</span>'}</div></div><div class="box-front"><span>${o?.id||'Klar for neste ordre'}</span></div><div class="box-lid"><span class="packing-tape"></span>${o?.labelApplied?`<div class="parcel-address-label">${carrierLogo(o.shipping)}<strong>${esc(o.patient)}</strong><small>${esc(o.shipping.place)}</small><div class="barcode"></div><b>${o.tracking}</b></div>`:''}</div></div><p class="parcel-state">${!o?'Ingen aktiv ordre':o.labelApplied?'Klar for transport':o.packStage==='printing'?'Skriver ut fraktetikett':o.packStage==='closing'?'Lukker esken':items.length+' varer i esken'}</p></div>`}
function doctorLockScreen(){return `<main class="epr-lock-screen"><section class="epr-lock-window" aria-labelledby="lockTitle"><div class="epr-lock-title">Pasientsky · Låst arbeidsstasjon</div><div class="epr-lock-body"><span class="epr-lock-icon">${icon('shield-check')}</span><h1 id="lockTitle">Skjermen er låst</h1><div class="epr-lock-user">${icon('person-circle')}<div><small>Pålogget bruker</small><strong>Martin Dahl</strong><span>MDAL · Fjordbyen legesenter</span></div></div><form onsubmit="staffSignIn(event)"><label for="doctorPin">PIN-kode</label><input id="doctorPin" name="pin" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" autocomplete="off" required aria-describedby="staffLoginError"><button type="button" class="fill-example staff-fill" onclick="fillStaffLogin(this)">Fyll ut ${icon('arrow-right')}</button><p id="staffLoginError" role="alert"></p><button type="submit" class="epr-unlock-button">Lås opp</button></form></div><div class="epr-lock-bottom">Pasientsky · Elektronisk pasientjournal</div></section></main>`}
render();
